{'command': 'python3 - <<'PY'
import json, textwrap, os
p='/tmp/taxjudge-bundles/E31/trajectory.jsonl'
out='/tmp/taxjudge_E31_readable.txt'
with open(out,'w') as w:
  for idx,line in enumerate(open(p),1):
    obj=json.loads(line)
    typ=obj.get('type')
    if typ not in ('user','assistant','system','attachment','queue-operation'): continue
    w.write(f'\n\n===== EVENT {idx} TYPE {typ} =====\n')
    if typ in ('system','attachment','queue-operation'):
      w.write(json.dumps(obj,ensure_ascii=False,indent=2)[:10000])
      continue
    msg=obj.get('message',{})
    w.write(f"role={msg.get('role')} id={obj.get('messageId') or msg.get('id')}\n")
    content=msg.get('content')
    if isinstance(content,str):
      w.write(content+'\n')
    else:
      for c in content or []:
        if isinstance(c,str):
          w.write(c+'\n')
        elif isinstance(c,dict):
          t=c.get('type')
          if t=='thinking':
            th=c.get('thinking','')
            if th.strip(): w.write('[THINKING] '+th[:500]+'\n')
            else: w.write('[THINKING empty]\n')
          elif t=='text':
            w.write(c.get('text','')+'\n')
          elif t=='tool_use':
            w.write(f"[TOOL_USE {c.get('name')} id={c.get('id')}]\n")
            w.write(json.dumps(c.get('input'),ensure_ascii=False,indent=2)+'\n')
          elif t=='tool_result':
            cont=c.get('content')
            w.write(f"[TOOL_RESULT for={c.get('tool_use_id')} is_error={c.get('is_error')}]\n")
            if isinstance(cont,str):
              w.write(cont[:20000]+'\n')
            else:
              w.write(json.dumps(cont,ensure_ascii=False,indent=2)[:20000]+'\n')
          else:
            w.write('[CONTENT '+t+'] '+json.dumps(c,ensure_ascii=False)[:1000]+'\n')
print(out, os.path.getsize(out))
